import {
  Callout,
  Card,
  CardBody,
  CardHeader,
  Code,
  Divider,
  Grid,
  H1,
  H2,
  H3,
  Pill,
  Row,
  Spacer,
  Stack,
  Stat,
  Table,
  Text,
  useCanvasState,
  useHostTheme,
} from "cursor/canvas";

type Phase = "ingest" | "query";

type Step = {
  id: string;
  n: number;
  phase: Phase;
  title: string;
  oneLiner: string;
  who: string;
  input: string;
  output: string;
  token: string;
  detail: string[];
  rules: string[];
};

const STEPS: Step[] = [
  {
    id: "s0",
    n: 1,
    phase: "ingest",
    title: "规则抽名词 S₀",
    oneLiner: "扫全书 A1 正文，用形态规则抽出候选名词。",
    who: "台 · 0 LLM",
    input: "全书 chunks · atomSearchText(T)",
    output: "S₀：候选名词多重集（未去重）",
    token: "0",
    detail: [
      "遍历可检索 atom，取 atomSearchText 作为正文。",
      "形态规则：拉丁专名 / 汉字 2–8 连字等；停用与过短串丢掉。",
      "不要用 tokenizeQuery（BM25 单字/二元会炸表）。",
      "建库时写入；提问只读，不每问重抽。",
    ],
    rules: [
      "规则 = 廉价高召回候选，不声称「全部名词」。",
      "本步允许重复出现，去重留给第 4 步。",
    ],
  },
  {
    id: "s1",
    n: 2,
    phase: "ingest",
    title: "遮盖 S₀ → 残文 R",
    oneLiner: "把已抽出的名词从正文里 mask 掉，留下漏网文本。",
    who: "台 · 0 LLM",
    input: "全书 T + S₀ 表面形",
    output: "残文 R（按章/strand 可切分）",
    token: "0",
    detail: [
      "对 S₀ 表面形做大小写不敏感匹配后遮盖。",
      "优先同长占位（如 ____），避免硬删导致邻句粘连、诱幻觉。",
      "R 仍可能很长 → 按走廊/strand 切片，供下一步分片喂模型。",
    ],
    rules: [
      "遮的是表面串，不是语义簇。",
      "目的：逼出规则没扫到的专名，不是再做全文摘要。",
    ],
  },
  {
    id: "s2",
    n: 3,
    phase: "ingest",
    title: "LLM 从 R 补抽 S₁",
    oneLiner: "对残文分片，让模型只吐「本片新名词」。",
    who: "LLM · 建库可开关",
    input: "残文切片 Rᵢ",
    output: "S₁：补召名词",
    token: "建库摊销",
    detail: [
      "每片提示：只输出本片出现、且不在已遮名单里的名词。",
      "台侧合并各片 → S₁。",
      "可作开关：S₀ 导航够用时先关，召回不够再开。",
    ],
    rules: [
      "模型补召，不发明书外词（输出须能在 R 里定位）。",
      "成本在建库，不进每问热成本。",
    ],
  },
  {
    id: "s3",
    n: 4,
    phase: "ingest",
    title: "去重得名词表 S",
    oneLiner: "同一词（忽略大小写）只留一条，得到喂勾选的薄表。",
    who: "台 · 0 LLM",
    input: "S₀ ∪ S₁",
    output: "S：去重名词表 + df / bookKeys[]",
    token: "0",
    detail: [
      "去重定义：表面完全同一词，大小写不管 → 一条。",
      "例：Lacan / lacan / LACAN → 一条；不做「拉康≈lacan」模糊并簇。",
      "表项可挂 df、出现过的 bookKeys[]，供定位；给 LLM 看的主要是名词列。",
      "S 是闭集：后面勾选合法空间 = S，禁止造词。",
    ],
    rules: [
      "递送粗筛/勾选 LLM 的必须是去重后的 S。",
      "去重后仍长 → 下一步分批，不靠再并簇硬压长度。",
    ],
  },
  {
    id: "s4",
    n: 5,
    phase: "query",
    title: "LLM 勾选相关名词 S_q",
    oneLiner: "问句 × 去重 S（过长分批）→ 只回传本批 ⟦n⟧。",
    who: "LLM · 每问",
    input: "Q_now + S（或粗筛/分批后的子集）",
    output: "S_q：与问相关的书内名词",
    token: "薄窗（名词列）",
    detail: [
      "语义只发生在这一跳：意译问句也可勾出书内「拉康/Lacan」。",
      "不要求用户用词与书面对齐；勾出的是书里的词。",
      "S 过长：分批勾选，台并成 S_q；可选词面/embed 只对 S 项粗筛后再喂。",
      "JSON 只许 ⟦n⟧；合法空间 = 本窗 S 子集。",
    ],
    rules: [
      "选择题，不是造词题。",
      "后面定位用的就是这些书内词，不是问句原词。",
    ],
  },
  {
    id: "s5",
    n: 6,
    phase: "query",
    title: "字符串定位全部出现点",
    oneLiner: "用 S_q 在全书做词面匹配，锁 bookKey / 偏移。",
    who: "台 · 0 LLM",
    input: "S_q + 全书 T",
    output: "命中点 Hit[]：noun · bookKey · page · span",
    token: "0",
    detail: [
      "大小写不敏感 includes / 正则即可。",
      "每个 s∈S_q 收集全部出现，不抽样。",
      "地址硬：可逆打开正文，不靠向量近邻。",
      "不需要 TOC 缩域；全文书内定位即导航。",
    ],
    rules: [
      "定位串 = S_q 书内表面形。",
      "命中爆炸时可用上限/抽样策略，但不回到 toc_nav 主闸。",
    ],
  },
  {
    id: "s6",
    n: 7,
    phase: "query",
    title: "命中点 → 拓扑名词袋",
    oneLiner: "每个出现点取前后各 n 个「不同名」名词，成集合。",
    who: "台 · 0 LLM",
    input: "Hit[] + 全书名词序列",
    output: "拓扑袋 Bag[]（带地址，袋内异名词）",
    token: "0（组袋）",
    detail: [
      "在命中点左右扫名词序列，取与该命中词不同的前后各 n 个。",
      "输出集合（袋内可再去重防刷屏）；不去重的是「跨命中点的多重袋」。",
      "袋挂地址（bookKey / span），仍不灌整段 T。",
      "这是给 decide 的薄证据：相关名词出现在何种名词邻域里。",
    ],
    rules: [
      "前后 n = 异名词个数，不是 n 字符、也不是整段正文。",
      "拓扑袋 ≠ 最终段落；过闸才开 T。",
    ],
  },
  {
    id: "s7",
    n: 8,
    phase: "query",
    title: "decide 闸段落 → infer",
    oneLiner: "decide 看拓扑袋判真相关段落；过闸薄窗正文递 infer。",
    who: "decide → infer",
    input: "Bag[]（⟦n⟧ 槽）+ 过闸后 T",
    output: "prospect → 过闸 book 正文 → ι / path",
    token: "decide 薄；infer 只吃过闸 T",
    detail: [
      "decide 输入：地址 + 拓扑名词集（材料槽 ⟦n⟧），判哪些命中点/段落支撑 Q。",
      "relevance / 三态照旧；可铸 prospect 后进 infer。",
      "infer 只接收 decide 过闸段落的正文 T（薄窗），不扫章、不跑 toc_nav。",
      "与主流 RAG 的差在召回精度：锁词定位 + 拓扑再闸，再生成。",
    ],
    rules: [
      "谁判相关：decide；谁吃正文：infer（及 decide 过闸后按需开 T）。",
      "TOC 不参与本热路径。",
    ],
  },
];

const PIPELINE_ONE_LINERS = STEPS.map(
  (s) => `${s.n}. ${s.title.replace(/S[₀₁₂q]?/g, (m) => m)}`,
);

export default function NounTableRetrievePipeline() {
  const theme = useHostTheme();
  const [selectedId, setSelectedId] = useCanvasState("selectedStep", "s4");
  const selected = STEPS.find((s) => s.id === selectedId) ?? STEPS[4]!;
  const ingest = STEPS.filter((s) => s.phase === "ingest");
  const query = STEPS.filter((s) => s.phase === "query");

  return (
    <Stack gap={20} style={{ maxWidth: 960, margin: "0 auto", padding: 20 }}>
      <Stack gap={8}>
        <H1>名词表找材料 · 全流程</H1>
        <Text tone="secondary">
          Docuverse 检索热路径共识：用书内名词表导航，替代 toc_nav；语义只用于从
          S 勾词，精度靠书内词定位与拓扑袋，decide 闸后再喂 infer。
        </Text>
      </Stack>

      <Callout tone="info" title="凝练 8 步（一条热路径）">
        <Text>
          建库：规则抽 S₀ → 遮盖得残文 R → LLM 补抽 S₁ → 去重得 S。每问：勾选 S_q
          → 字符串定位命中点 → 每点取前后 n 个异名词成拓扑袋 → decide 判真相关段落
          → 过闸正文递 infer。不去 TOC。
        </Text>
      </Callout>

      <Grid columns={4} gap={12}>
        <Stat value="4" label="建库步（摊销）" />
        <Stat value="4" label="每问步" />
        <Stat value="去重 S" label="勾选闭集" tone="accent" />
        <Stat value="无 TOC" label="热路径闸" />
      </Grid>

      <Card>
        <CardHeader trailing={<Pill tone="neutral">点击一步看详情</Pill>}>
          步骤条
        </CardHeader>
        <CardBody>
          <Stack gap={10}>
            <Text size="small" tone="tertiary" weight="medium">
              建库（一次）
            </Text>
            <Row gap={8} wrap>
              {ingest.map((s) => (
                <StepChip
                  key={s.id}
                  step={s}
                  active={s.id === selected.id}
                  onSelect={() => setSelectedId(s.id)}
                />
              ))}
            </Row>
            <Divider />
            <Text size="small" tone="tertiary" weight="medium">
              每问（热路径）
            </Text>
            <Row gap={8} wrap>
              {query.map((s) => (
                <StepChip
                  key={s.id}
                  step={s}
                  active={s.id === selected.id}
                  onSelect={() => setSelectedId(s.id)}
                />
              ))}
            </Row>
          </Stack>
        </CardBody>
      </Card>

      <Grid columns={2} gap={16}>
        <Card
          style={{
            borderColor:
              selected.phase === "ingest"
                ? theme.accent.primary
                : theme.stroke.secondary,
          }}
        >
          <CardHeader
            trailing={
              <Pill tone={selected.phase === "ingest" ? "info" : "neutral"}>
                {selected.phase === "ingest" ? "建库" : "每问"}
              </Pill>
            }
          >
            第 {selected.n} 步 · {selected.title}
          </CardHeader>
          <CardBody>
            <Stack gap={12}>
              <Text weight="medium">{selected.oneLiner}</Text>
              <Grid columns={2} gap={8}>
                <Meta label="执行方" value={selected.who} />
                <Meta label="Token" value={selected.token} />
              </Grid>
              <Meta label="输入" value={selected.input} />
              <Meta label="输出" value={selected.output} />
              <Divider />
              <H3>流程</H3>
              <Stack gap={6}>
                {selected.detail.map((line) => (
                  <Text key={line} size="small">
                    · {line}
                  </Text>
                ))}
              </Stack>
              <H3>约束</H3>
              <Stack gap={6}>
                {selected.rules.map((line) => (
                  <Text key={line} size="small" tone="secondary">
                    · {line}
                  </Text>
                ))}
              </Stack>
            </Stack>
          </CardBody>
        </Card>

        <Stack gap={16}>
          <Card>
            <CardHeader>数据怎么变薄</CardHeader>
            <CardBody>
              <Table
                headers={["阶段", "窗里是什么", "目的"]}
                rows={[
                  ["S 勾选", "去重名词列（可分批）", "语义只挑词"],
                  ["定位", "无 LLM", "书内串锁地址"],
                  ["拓扑袋", "±n 异名词集合", "邻域语义给 decide"],
                  ["decide→infer", "过闸后才开 T", "正文 token 最小化"],
                ]}
                columnAlign={["left", "left", "left"]}
              />
            </CardBody>
          </Card>

          <Card>
            <CardHeader>与旧 toc_nav 对照</CardHeader>
            <CardBody>
              <Table
                headers={["", "旧热路径", "名词表热路径"]}
                rows={[
                  ["首跳", "LLM 选 strand", "LLM 从 S 勾 S_q"],
                  ["缩域", "章 ∩ A1 全量门", "命中点地址"],
                  ["decide 先看", "多段全文 T", "拓扑名词袋"],
                  ["TOC", "每问必跑", "不参与检索"],
                ]}
                columnAlign={["left", "left", "left"]}
              />
            </CardBody>
          </Card>

          <Callout tone="neutral" title="召回本质">
            <Text size="small">
              与主流切块向量 RAG 的差主要在召回精度：勾选闭集 S → 字符串真命中 →
              拓扑再闸。意译问句靠勾选跳到书内词；其后全程用这些词，不靠问句原词匹配正文。
            </Text>
          </Callout>
        </Stack>
      </Grid>

      <Spacer height={4} />
      <H2>全链路一览</H2>
      <Table
        headers={["#", "步", "相位", "执行", "输出"]}
        rows={STEPS.map((s) => [
          String(s.n),
          s.title,
          s.phase === "ingest" ? "建库" : "每问",
          s.who,
          s.output,
        ])}
        rowTone={STEPS.map((s) =>
          s.id === selected.id ? ("info" as const) : undefined,
        )}
        columnAlign={["right", "left", "left", "left", "left"]}
      />

      <Text size="small" tone="tertiary">
        源：本会话共识 · 相对现码 autoFlow toc_nav 为设计目标热路径 ·{" "}
        {PIPELINE_ONE_LINERS.join(" → ")}
      </Text>
    </Stack>
  );
}

function StepChip(props: {
  step: Step;
  active: boolean;
  onSelect: () => void;
}) {
  const theme = useHostTheme();
  const { step, active, onSelect } = props;
  return (
    <button
      type="button"
      onClick={onSelect}
      style={{
        cursor: "pointer",
        border: `1px solid ${active ? theme.accent.primary : theme.stroke.secondary}`,
        background: active ? theme.fill.secondary : theme.bg.elevated,
        color: theme.text.primary,
        padding: "8px 10px",
        borderRadius: 6,
        textAlign: "left",
        minWidth: 120,
      }}
    >
      <Stack gap={2}>
        <Text size="small" tone="tertiary">
          {step.n}
        </Text>
        <Text size="small" weight="medium">
          {step.title}
        </Text>
      </Stack>
    </button>
  );
}

function Meta(props: { label: string; value: string }) {
  return (
    <Stack gap={2}>
      <Text size="small" tone="tertiary">
        {props.label}
      </Text>
      <Code>{props.value}</Code>
    </Stack>
  );
}

{
  "name": "docuverse-decide-eval",
  "private": true,
  "version": "0.1.0",
  "type": "module",
  "description": "Standalone decide material-accuracy harness (does not modify main Docuverse app)",
  "scripts": {
    "eval": "tsx scripts/eval-decide.ts",
    "typecheck": "tsc --noEmit"
  },
  "devDependencies": {
    "@types/node": "^24.13.3",
    "tsx": "^4.20.5",
    "typescript": "~5.9.2"
  }
}

/** Minimal A1 types for decide material eval (from Docuverse BookIndex). */

export type PlaceFaces = {
  text?: { content: string }
  fig?: { note: string; figId?: string }
}

export type AChunk = {
  ord: number
  id: string
  page: number
  bbox: [number, number, number, number]
  key: string
  kind: string
  faces: PlaceFaces
  content: string
}

export type BookIndex = {
  docId: string
  stream?: string
  chunks: AChunk[]
  builtAt?: number
}

export type SemanticSection = {
  nodeId: string
  title: string
  page?: number
  pageRange?: { startPage: number; endPage: number }
}

export type BookSemanticIndex = {
  docId: string
  sections: SemanticSection[]
  builtAt?: number
}

export type CorpusPack = {
  kind: 'docuverse-corpus'
  version: 1 | 2
  label: string
  docId: string
  exportedAt: number
  bookIndex: BookIndex
  semanticIndex: BookSemanticIndex | null
  pages?: unknown[]
}

import type { AChunk } from './types'

/** Port of hybridRetrieve.atomSearchText / isRetrievableAtom / tokenizeQuery */
export function atomSearchText(input: {
  kind: string
  content: string
  faces: {
    text?: { content: string }
    fig?: { note: string; figId?: string }
  }
}): string {
  const text = input.faces.text?.content?.trim()
  if (text && text.length >= 8) return text
  const raw = input.content.trim()
  if (raw && !raw.startsWith('[FIG:') && raw.length >= 8) return raw
  if (text) return text
  const note = input.faces.fig?.note?.trim() ?? ''
  return note
    .replace(/请依据可见版面回答[^。]*。?/g, '')
    .replace(/勿编造未提供的文字[^。]*。?/g, '')
    .replace(/无文字层\/未OCR[^。]*。?/g, '')
    .trim()
}

export function tokenizeQuery(text: string): string[] {
  const norm = text.toLowerCase().replace(/\s+/g, ' ').trim()
  if (!norm) return []
  const out: string[] = []
  const latin = norm.match(/[a-z0-9]{2,}/g)
  if (latin) out.push(...latin)
  const cjk = norm.replace(/[a-z0-9\s.,;:!?'"()[\]{}<>/\\|_+=\-@#$%^&*`~]+/g, '')
  for (let i = 0; i < cjk.length; i++) {
    out.push(cjk[i]!)
    if (i + 1 < cjk.length) out.push(cjk.slice(i, i + 2))
  }
  return out
}

export function isRetrievableAtom(input: {
  kind: string
  content: string
  faces: {
    text?: { content: string }
    fig?: { note: string }
  }
}): boolean {
  const t = atomSearchText(input)
  if (t.length < 4) return false
  if (input.kind === 'fig' && t.length < 24 && !input.faces.text) return false
  return true
}

export function chunkT(chunk: AChunk): string {
  return atomSearchText(chunk)
}

export function orderedRetrievableBookKeys(
  bookIndex: { chunks: AChunk[] },
): string[] {
  return [...bookIndex.chunks]
    .filter((c) => isRetrievableAtom(c))
    .sort((a, b) => a.page - b.page || a.ord - b.ord)
    .map((c) => c.key)
}

/**
 * Port of src/arch/qCoreBookHits.ts — imports rewritten for this harness.
 */

import {
  atomSearchText,
  isRetrievableAtom,
  orderedRetrievableBookKeys,
  tokenizeQuery,
} from './text'
import type { BookIndex } from './types'

const CJK_ALIASES: Record<string, string[]> = {
  拉康: ['lacan', 'lacanien', 'lacanienne'],
  弗洛伊德: ['freud', 'freudien', 'freudienne'],
  荣格: ['jung', 'jungien'],
  德勒兹: ['deleuze'],
  瓜塔里: ['guattari'],
  加塔利: ['guattari'],
  马克思: ['marx', 'marxiste'],
  黑格尔: ['hegel', 'hégel'],
  尼采: ['nietzsche'],
  萨特: ['sartre'],
  福柯: ['foucault'],
}

const Q_NOISE = new Set([
  '如何',
  '什么',
  '怎么',
  '怎样',
  '批判',
  '批评',
  '理解',
  '意思',
  '是否',
  '提到',
  '的呢',
  '呢',
  '吗',
  '啊',
  '呀',
  '吧',
])

export function qCoreNeedles(question: string): string[] {
  const q = question.trim()
  if (!q) return []
  const out = new Set<string>()

  const names = Object.keys(CJK_ALIASES).sort((a, b) => b.length - a.length)
  for (const name of names) {
    if (q.includes(name)) {
      out.add(name)
      for (const a of CJK_ALIASES[name] ?? []) out.add(a)
    }
  }

  const cjkRuns = q.match(/[\u4e00-\u9fff]{2,8}/g) ?? []
  for (const run of cjkRuns) {
    if (Q_NOISE.has(run)) continue
    if ([...out].some((n) => /[\u4e00-\u9fff]/.test(n) && run.includes(n))) {
      continue
    }
    let hasNoise = false
    for (const noise of Q_NOISE) {
      if (run.includes(noise)) {
        hasNoise = true
        break
      }
    }
    if (hasNoise) continue
    if (run.length >= 2 && run.length <= 6) out.add(run)
  }

  for (const t of tokenizeQuery(q)) {
    if (/^[a-z]{4,}$/i.test(t)) out.add(t.toLowerCase())
  }

  for (const noise of Q_NOISE) out.delete(noise)
  return [...out].filter((n) => {
    if (/[\u4e00-\u9fff]/.test(n) && n.length > 6) return false
    return true
  })
}

export function textHitsQCore(
  text: string,
  needles: ReadonlyArray<string>,
): boolean {
  const t = text.toLowerCase()
  if (!t.trim() || needles.length === 0) return false
  return needles.some((n) => {
    const needle = n.toLowerCase()
    return needle.length >= 2 && t.includes(needle)
  })
}

export function prioritizeBookKeysByQCore(input: {
  bookKeys: ReadonlyArray<string>
  bookIndex: BookIndex
  question: string
}): { keys: string[]; hitKeys: string[]; needles: string[]; note: string } {
  const needles = qCoreNeedles(input.question)
  if (needles.length === 0 || input.bookKeys.length === 0) {
    return {
      keys: [...input.bookKeys],
      hitKeys: [],
      needles,
      note: '问核优先 · 无 needle / 空队列',
    }
  }
  const hitKeys: string[] = []
  const rest: string[] = []
  for (const k of input.bookKeys) {
    const chunk = input.bookIndex.chunks.find((c) => c.key === k)
    const t = chunk ? atomSearchText(chunk) : ''
    if (textHitsQCore(t, needles)) hitKeys.push(k)
    else rest.push(k)
  }
  return {
    keys: [...hitKeys, ...rest],
    hitKeys,
    needles,
    note:
      `问核优先 · needle=[${needles.slice(0, 8).join(',')}]` +
      ` · 命中×${hitKeys.length}/${input.bookKeys.length}`,
  }
}

export function bookKeysHittingQCore(input: {
  bookIndex: BookIndex
  question: string
  allowedKeys?: ReadonlySet<string> | null
  maxKeys?: number
}): { keys: string[]; needles: string[]; note: string } {
  const needles = qCoreNeedles(input.question)
  if (needles.length === 0) {
    return { keys: [], needles, note: '问核词面 · 无专名 needle' }
  }
  const maxKeys = input.maxKeys ?? 24
  const hit = new Set<string>()
  for (const c of input.bookIndex.chunks) {
    if (input.allowedKeys && !input.allowedKeys.has(c.key)) continue
    if (!isRetrievableAtom(c)) continue
    if (!textHitsQCore(atomSearchText(c), needles)) continue
    hit.add(c.key)
  }
  const keys = orderedRetrievableBookKeys(input.bookIndex)
    .filter((k) => hit.has(k))
    .slice(0, maxKeys)
  return {
    keys,
    needles,
    note:
      `问核词面 · needle=[${needles.slice(0, 8).join(',')}]` +
      ` · 命中×${keys.length}` +
      (input.allowedKeys ? '（走廊内）' : '（全书）'),
  }
}

/** Port of src/arch/prospectRelevance.ts */

export const MIN_PROSPECT_RELEVANCE = 3

export function normalizeRelevance(raw: unknown): number | null {
  if (raw == null || raw === '') return null
  const n = typeof raw === 'number' ? raw : Number(String(raw).trim())
  if (!Number.isFinite(n)) return null
  if (n > 0 && n <= 1) return Math.max(1, Math.min(5, Math.round(n * 5)))
  return Math.max(1, Math.min(5, Math.round(n)))
}

export function relevanceAllowsInfer(
  relevance: number | null | undefined,
): boolean {
  const r = relevance == null ? MIN_PROSPECT_RELEVANCE : relevance
  return r >= MIN_PROSPECT_RELEVANCE
}

/** Port of src/arch/parallelLlmBatch.ts (chunk + limited concurrency + early abort). */

export function chunkUniqueKeys(
  keys: ReadonlyArray<string>,
  batchSize: number,
): string[][] {
  const seen = new Set<string>()
  const uniq: string[] = []
  for (const k of keys) {
    if (!k || seen.has(k)) continue
    seen.add(k)
    uniq.push(k)
  }
  const size = Math.max(1, batchSize)
  const out: string[][] = []
  for (let i = 0; i < uniq.length; i += size) {
    out.push(uniq.slice(i, i + size))
  }
  return out
}

export async function runBatchesParallel<T>(input: {
  batches: ReadonlyArray<unknown>
  concurrency: number
  run: (batchIndex: number, signal: AbortSignal) => Promise<T>
  shouldStop?: (results: ReadonlyArray<T>) => boolean
}): Promise<{
  results: T[]
  stoppedEarly: boolean
  note: string
}> {
  const n = input.batches.length
  const concurrency = Math.max(1, Math.min(input.concurrency, n || 1))
  const results: T[] = new Array(n)
  const controllers = Array.from({ length: n }, () => new AbortController())
  let next = 0
  let done = 0
  let stoppedEarly = false
  let aborted = 0

  async function worker() {
    while (true) {
      if (stoppedEarly) return
      const i = next++
      if (i >= n) return
      const ctrl = controllers[i]!
      if (ctrl.signal.aborted) {
        aborted++
        done++
        continue
      }
      try {
        results[i] = await input.run(i, ctrl.signal)
      } catch (e) {
        if (ctrl.signal.aborted) {
          aborted++
        } else {
          throw e
        }
      }
      done++
      const finished = results.filter((_, j) => j < done && results[j] !== undefined)
      if (!stoppedEarly && input.shouldStop?.(finished as T[])) {
        stoppedEarly = true
        for (let j = 0; j < n; j++) {
          if (results[j] === undefined) controllers[j]!.abort()
        }
      }
    }
  }

  await Promise.all(Array.from({ length: concurrency }, () => worker()))
  return {
    results: results.filter((r) => r !== undefined) as T[],
    stoppedEarly,
    note:
      `并行批 · 完成×${done}/${n}` +
      (stoppedEarly ? ` · 早停取消×${aborted}` : ''),
  }
}

/**
 * Port of src/arch/parallelLlmBatch.ts — decide-eval harness.
 */

export function dedupePreserveOrder(keys: string[]): string[] {
  const seen = new Set<string>()
  const out: string[] = []
  for (const raw of keys) {
    const k = raw.trim()
    if (!k || seen.has(k)) continue
    seen.add(k)
    out.push(k)
  }
  return out
}

export function chunkKeys<T>(items: T[], size: number): T[][] {
  if (size <= 0) return [items]
  const out: T[][] = []
  for (let i = 0; i < items.length; i += size) {
    out.push(items.slice(i, i + size))
  }
  return out
}

export function chunkUniqueKeys(keys: string[], size: number): string[][] {
  return chunkKeys(dedupePreserveOrder(keys), size)
}

export function isAbortError(e: unknown): boolean {
  if (!e || typeof e !== 'object') return false
  const name = String((e as { name?: string }).name ?? '')
  if (name === 'AbortError') return true
  const msg = e instanceof Error ? e.message : String(e)
  return /abort|aborted|The user aborted/i.test(msg)
}

export async function runBatchesParallel<TBatch, TResult>(input: {
  batches: TBatch[]
  concurrency: number
  signal?: AbortSignal
  run: (batch: TBatch, index: number, signal: AbortSignal) => Promise<TResult>
  shouldStop?: (result: TResult, index: number) => boolean
}): Promise<{
  results: Array<
    | { index: number; ok: true; value: TResult }
    | { index: number; ok: false; aborted: boolean; note: string }
  >
  stoppedEarly: boolean
  note: string
}> {
  const n = input.batches.length
  if (n === 0) {
    return { results: [], stoppedEarly: false, note: '并行批 · 空' }
  }
  const controller = new AbortController()
  const onParent = () => {
    try {
      controller.abort()
    } catch {
      /* */
    }
  }
  if (input.signal) {
    if (input.signal.aborted) onParent()
    else input.signal.addEventListener('abort', onParent, { once: true })
  }
  const signal = controller.signal
  const concurrency = Math.max(1, Math.min(input.concurrency, n))
  const results: Array<
    | { index: number; ok: true; value: TResult }
    | { index: number; ok: false; aborted: boolean; note: string }
  > = new Array(n)
  let next = 0
  let stoppedEarly = false
  let inFlight = 0

  await new Promise<void>((resolve) => {
    const kick = () => {
      if (signal.aborted && inFlight === 0) {
        while (next < n) {
          results[next] = {
            index: next,
            ok: false,
            aborted: true,
            note: '并行早停 · 未启动',
          }
          next++
        }
        resolve()
        return
      }
      while (inFlight < concurrency && next < n && !signal.aborted) {
        const index = next++
        inFlight++
        const batch = input.batches[index]!
        void input
          .run(batch, index, signal)
          .then((value) => {
            results[index] = { index, ok: true, value }
            if (!stoppedEarly && input.shouldStop?.(value, index)) {
              stoppedEarly = true
              try {
                controller.abort()
              } catch {
                /* */
              }
            }
          })
          .catch((e) => {
            const aborted = signal.aborted || isAbortError(e)
            results[index] = {
              index,
              ok: false,
              aborted,
              note: aborted
                ? '并行早停 · 已取消'
                : e instanceof Error
                  ? e.message
                  : '并行批失败',
            }
          })
          .finally(() => {
            inFlight--
            if (next >= n && inFlight === 0) resolve()
            else kick()
          })
      }
      if (signal.aborted && inFlight === 0) {
        while (next < n) {
          results[next] = {
            index: next,
            ok: false,
            aborted: true,
            note: '并行早停 · 未启动',
          }
          next++
        }
        resolve()
      }
    }
    kick()
  })

  if (input.signal) input.signal.removeEventListener('abort', onParent)
  const done = results.filter((r) => r?.ok).length
  const aborted = results.filter((r) => r && !r.ok && r.aborted).length
  return {
    results,
    stoppedEarly,
    note:
      `并行批 · 完成×${done}/${n}` +
      (stoppedEarly ? ` · 早停取消×${aborted}` : ''),
  }
}

/** JSON extract + decide prospect parse (material-eval subset). */

import {
  normalizeRelevance,
  relevanceAllowsInfer,
} from './prospectRelevance'
import {
  expandDoorplatesInJsonValue,
  resolveWindowDoorplate,
  type WindowAliasTable,
} from './windowAlias'

export function extractJsonObject(raw: string): Record<string, unknown> | null {
  const trimmed = raw.trim()
  const fence = trimmed.match(/```(?:json)?\s*([\s\S]*?)```/i)
  const body = (fence?.[1] ?? trimmed).trim()
  const start = body.indexOf('{')
  if (start < 0) return null
  const end = body.lastIndexOf('}')
  if (end <= start) return null
  try {
    const obj = JSON.parse(body.slice(start, end + 1))
    return obj && typeof obj === 'object' ? (obj as Record<string, unknown>) : null
  } catch {
    return null
  }
}

function asStatus(raw: unknown): string | null {
  if (typeof raw !== 'string') return null
  const s = raw.trim().toLowerCase()
  if (s === 'unread' || s === 'sufficient' || s === 'insufficient') return s
  return null
}

export type MintableProspect = {
  bookKey: string
  prospect: string
  status: string
  relevance: number | null
}

export function parseDecideMintables(
  llmText: string,
  aliasTable: WindowAliasTable,
): { mintables: MintableProspect[]; note: string; rawOk: boolean } {
  let obj = extractJsonObject(llmText)
  if (obj) {
    obj = expandDoorplatesInJsonValue(obj, aliasTable) as Record<string, unknown>
  }
  if (!obj) {
    return { mintables: [], note: 'decide 硬闸：无法解析 JSON', rawOk: false }
  }

  const rows: unknown[] = []
  if (Array.isArray(obj.prospects)) rows.push(...obj.prospects)
  if (Array.isArray(obj.keeps)) rows.push(...obj.keeps)

  const statusByKey = new Map<string, string>()
  if (Array.isArray(obj.keyStatuses)) {
    for (const row of obj.keyStatuses) {
      if (!row || typeof row !== 'object') continue
      const r = row as Record<string, unknown>
      const rawKey = String(r.key ?? r.bookKey ?? r.briefKey ?? '')
      const full =
        resolveWindowDoorplate(rawKey, aliasTable) ??
        (aliasTable.fullOf.has(rawKey) ? rawKey : rawKey)
      const st = asStatus(r.status)
      if (full && st) statusByKey.set(full, st)
    }
  }

  const mintables: MintableProspect[] = []
  const seen = new Set<string>()
  for (const row of rows) {
    if (!row || typeof row !== 'object') continue
    const r = row as Record<string, unknown>
    const rawKey = String(r.bookKey ?? r.briefKey ?? r.key ?? '')
    const bookKey =
      resolveWindowDoorplate(rawKey, aliasTable) ??
      (aliasTable.fullKeys.includes(rawKey) ? rawKey : '')
    if (!bookKey || !aliasTable.fullKeys.includes(bookKey)) continue
    const prospect = String(r.prospect ?? r.prospects ?? '').trim()
    const status =
      asStatus(r.status) ?? statusByKey.get(bookKey) ?? 'insufficient'
    const relevance = normalizeRelevance(r.relevance)
    if (status !== 'sufficient') continue
    if (!prospect) continue
    if (!relevanceAllowsInfer(relevance)) continue
    if (seen.has(bookKey)) continue
    seen.add(bookKey)
    mintables.push({ bookKey, prospect, status, relevance })
  }

  return {
    mintables,
    note: `decide parse · mintable×${mintables.length}`,
    rawOk: true,
  }
}

