const DECIDE_SYSTEM =
  '你是写信台 decide 工种。只根据本窗材料槽与 Q_now 判断哪些门能直接支撑解问。' +
  '只输出 JSON。门牌字段只许回传本窗 ⟦n⟧。thinking 关闭。'

function buildDecideUser(input: {
  question: string
  bookKeys: string[]
  bookIndex: BookIndex
  tMaxChars: number
}): { user: string; aliasTable: ReturnType<typeof buildWindowAliasTable> } {
  const aliasTable = buildWindowAliasTable(input.bookKeys)
  const needles = qCoreNeedles(input.question)
  const lines: string[] = []
  lines.push(`Q_now：${input.question}`, '')
  lines.push(
    '【实验·无 peek】decide 直读材料槽：上行 ⟦n⟧ 独占行，下行正文 T；' +
      'prospect 父门=该槽（JSON 只许回传 bookKey/briefKey/key=⟦n⟧）。',
    '',
  )
  const hitDoors: string[] = []
  for (const k of input.bookKeys) {
    const chunk = input.bookIndex.chunks.find((c) => c.key === k)
    const T = (chunk ? chunkT(chunk) : '').slice(0, input.tMaxChars)
    const tags: string[] = []
    if (!T.trim()) {
      tags.push(
        '【台侧·T 空】本门无原文，禁止编造；须 status=insufficient，prospects 勿写本门。',
      )
    }
    if (textHitsQCore(T, needles)) {
      hitDoors.push(`⟦${aliasTable.aliasOf.get(k)?.replace(/[^\d]/g, '') || '?'}⟧`)
      tags.push(
        `【问核提示】T 含 Q 专名（${needles.slice(0, 4).join('/')}）——逐门判解问相关；` +
          `专名≠充分，也≠默认不足。`,
      )
    }
    lines.push(
      formatDeskMaterialSlot({
        fullKey: k,
        table: aliasTable,
        body: T,
        tags,
      }),
    )
  }
  if (hitDoors.length > 0) {
    lines.push(
      `【问核提示】本窗有专名词面命中：逐门独立打分，禁止整窗一刀切 insufficient。`,
      '',
    )
  }
  lines.push(windowAliasContractHint(aliasTable), '')
  lines.push(
    '请只输出 JSON（可围栏）：\n' +
      '{\n' +
      '  "prospects": [{ "bookKey": "⟦n⟧", "prospect": "单行≤40字：该原文解 Q_now 的一种可能", "status": "sufficient", "relevance": 4 }],\n' +
      '  "keyStatuses": [{ "key": "⟦n⟧", "status": "unread|sufficient|insufficient" }]\n' +
      '}\n' +
      '硬规则：\n' +
      '- 只有能直接支撑解 Q_now 才写 prospects[]；须带 relevance 1–5；台侧 ≥3 才算命中材料。\n' +
      '- 仅点名/标题/旁例 → insufficient，勿因专名硬铸。\n' +
      '- bookKey/key 只许回传本窗 ⟦n⟧；prospect 单行≤40字。\n' +
      '- 窗内每个 ⟦n⟧ 都必须出现在 prospects 或 keyStatuses。\n' +
      '- 优先保证 JSON 完整可解析。',
  )
  return { user: lines.join('\n'), aliasTable }
}

function seedBookKeys(input: {
  bookIndex: BookIndex
  semanticIndex: BookSemanticIndex | null
  useTocUnion: boolean
  maxKeys: number
}): string[] {
  const all = orderedRetrievableBookKeys(input.bookIndex)
  if (!input.useTocUnion) return all.slice(0, input.maxKeys)
  const corridors = listTocCorridors(input.semanticIndex)
  if (corridors.length === 0) return all.slice(0, input.maxKeys)
  const allowedPages = new Set<number>()
  for (const c of corridors) {
    for (let p = c.startStrand; p <= c.endStrand; p++) allowedPages.add(p)
  }
  return all.filter((k) => {
    const chunk = input.bookIndex.chunks.find((c) => c.key === k)
    return chunk && allowedPages.has(chunk.page)
  }).slice(0, input.maxKeys)
}

export async function runDecideMaterial(input: {
  question: string
  bookIndex: BookIndex
  semanticIndex?: BookSemanticIndex | null
  llm: LlmConfig
  options?: DecideEvalOptions
  onProgress?: (msg: string) => void
}): Promise<DecideCaseResult> {
  const batchSize = input.options?.batchSize ?? 6
  const concurrency = input.options?.concurrency ?? 3
  const minProspects = input.options?.minProspects ?? 10
  const maxKeys = input.options?.maxKeys ?? 400
  const useTocUnion = input.options?.useTocUnion ?? false
  const tMaxChars = input.options?.tMaxChars ?? 1200

  const seed = seedBookKeys({
    bookIndex: input.bookIndex,
    semanticIndex: input.semanticIndex ?? null,
    useTocUnion,
    maxKeys,
  })
  const prio = prioritizeBookKeysByQCore({
    bookKeys: seed,
    bookIndex: input.bookIndex,
    question: input.question,
  })
  const ordered = prio.keys
  const batches = chunkUniqueKeys(ordered, batchSize)
  input.onProgress?.(
    `seed×${ordered.length} · ${prio.note} · 批×${batches.length}`,
  )

  const mintAccum = new Map<string, MintableProspect>()
  const batchNotes: string[] = []
  let promptTokens = 0
  let completionTokens = 0

  const parallel = await runBatchesParallel({
    batches,
    concurrency,
    run: async (batch, index, signal) => {
      input.onProgress?.(`decide 批 ${index + 1}/${batches.length} · ×${batch.length}`)
      const { user, aliasTable } = buildDecideUser({
        question: input.question,
        bookKeys: batch,
        bookIndex: input.bookIndex,
        tMaxChars,
      })
      const chat = await chatCompletions({
        config: input.llm,
        system: DECIDE_SYSTEM,
        user,
        signal,
      })
      if (!chat.ok) {
        return {
          mintables: [] as MintableProspect[],
          note: `批${index + 1} 失败 · ${chat.note}`,
          promptTokens: 0,
          completionTokens: 0,
        }
      }
      const parsed = parseDecideMintables(chat.content, aliasTable)
      return {
        mintables: parsed.mintables,
        note: `批${index + 1} · ${parsed.note}`,
        promptTokens: chat.usage?.prompt_tokens ?? 0,
        completionTokens: chat.usage?.completion_tokens ?? 0,
      }
    },
    shouldStop: (result) => {
      if (!result.ok) return false
      // accumulate check happens after; early stop based on running mint — approximate via result value size only within shouldStop is weak.
      // Use cumulative via closure after each success in a second pass — mirror autoFlow: stop when mintAccum >= min
      return false
    },
  })

  // Sequential accumulate with early-stop semantics: re-run style — prefer first batches in order
  // Parallel already ran; collect in index order and stop counting after minProspects for "predicted" set still includes all returned.
  const orderedResults = [...parallel.results].sort((a, b) => a.index - b.index)
  let stoppedEarly = parallel.stoppedEarly
  for (const r of orderedResults) {
    if (!r.ok) {
      batchNotes.push(r.note)
      continue
    }
    batchNotes.push(r.value.note)
    promptTokens += r.value.promptTokens
    completionTokens += r.value.completionTokens
    for (const m of r.value.mintables) {
      if (!mintAccum.has(m.bookKey)) mintAccum.set(m.bookKey, m)
    }
    if (mintAccum.size >= minProspects) {
      stoppedEarly = true
      break
    }
  }

  // Better early-stop: abort remaining mid-flight — implement proper shouldStop with shared Set
  // For v1, post-hoc truncate note is enough for scoring; tokens may include cancelled work if any.

  const mintables = [...mintAccum.values()]
  return {
    question: input.question,
    seedKeys: ordered,
    qCoreNote: prio.note,
    predictedBookKeys: mintables.map((m) => m.bookKey),
    mintables,
    batchNotes,
    stoppedEarly,
    promptTokens,
    completionTokens,
    note: `${parallel.note} · mintable×${mintables.length}` + (stoppedEarly ? ' · 达早停门槛' : ''),
  }
}

/** Proper early-stop variant: sequential batches (simpler token accounting for eval). */
export async function runDecideMaterialSequential(input: {
  question: string
  bookIndex: BookIndex
  semanticIndex?: BookSemanticIndex | null
  llm: LlmConfig
  options?: DecideEvalOptions
  onProgress?: (msg: string) => void
}): Promise<DecideCaseResult> {
  const batchSize = input.options?.batchSize ?? 6
  const minProspects = input.options?.minProspects ?? 10
  const maxKeys = input.options?.maxKeys ?? 400
  const useTocUnion = input.options?.useTocUnion ?? false
  const tMaxChars = input.options?.tMaxChars ?? 1200

  const seed = seedBookKeys({
    bookIndex: input.bookIndex,
    semanticIndex: input.semanticIndex ?? null,
    useTocUnion,
    maxKeys,
  })
  const prio = prioritizeBookKeysByQCore({
    bookKeys: seed,
    bookIndex: input.bookIndex,
    question: input.question,
  })
  const ordered = prio.keys
  const batches = chunkUniqueKeys(ordered, batchSize)
  const mintAccum = new Map<string, MintableProspect>()
  const batchNotes: string[] = []
  let promptTokens = 0
  let completionTokens = 0
  let stoppedEarly = false

  for (let i = 0; i < batches.length; i++) {
    const batch = batches[i]!
    input.onProgress?.(`decide 批 ${i + 1}/${batches.length} · ×${batch.length}`)
    const { user, aliasTable } = buildDecideUser({
      question: input.question,
      bookKeys: batch,
      bookIndex: input.bookIndex,
      tMaxChars,
    })
    const chat = await chatCompletions({
      config: input.llm,
      system: DECIDE_SYSTEM,
      user,
    })
    if (!chat.ok) {
      batchNotes.push(`批${i + 1} 失败 · ${chat.note}`)
      continue
    }
    promptTokens += chat.usage?.prompt_tokens ?? 0
    completionTokens += chat.usage?.completion_tokens ?? 0
    const parsed = parseDecideMintables(chat.content, aliasTable)
    batchNotes.push(`批${i + 1} · ${parsed.note}`)
    for (const m of parsed.mintables) {
      if (!mintAccum.has(m.bookKey)) mintAccum.set(m.bookKey, m)
    }
    if (mintAccum.size >= minProspects) {
      stoppedEarly = true
      break
    }
  }

  const mintables = [...mintAccum.values()]
  return {
    question: input.question,
    seedKeys: ordered,
    qCoreNote: prio.note,
    predictedBookKeys: mintables.map((m) => m.bookKey),
    mintables,
    batchNotes,
    stoppedEarly,
    promptTokens,
    completionTokens,
    note:
      `顺序批 · mintable×${mintables.length}` +
      (stoppedEarly ? ` · 早停≥${minProspects}` : ' · 扫完'),
  }
}

import type { BookIndex } from '../core/types'
import { pageOfKey, type EvalCase } from './loadCorpus'
import type { DecideCaseResult } from './runDecideMaterial'

export type CaseScore = {
  id: string
  hit: boolean
  precision: number
  recall: number
  predictedPages: number[]
  goldPages: number[]
  predictedBookKeys: string[]
  goldBookKeys: string[]
}

function resolveGold(input: {
  bookIndex: BookIndex
  c: EvalCase
}): { keys: Set<string>; pages: Set<number> } {
  const keys = new Set<string>(input.c.goldBookKeys ?? [])
  const pages = new Set<number>(input.c.goldPages ?? [])
  for (const k of keys) {
    const p = pageOfKey(input.bookIndex, k)
    if (p != null) pages.add(p)
  }
  // if only pages given, expand to keys on those pages
  if (keys.size === 0 && pages.size > 0) {
    for (const c of input.bookIndex.chunks) {
      if (pages.has(c.page)) keys.add(c.key)
    }
  }
  return { keys, pages }
}

export function scoreCase(input: {
  bookIndex: BookIndex
  evalCase: EvalCase
  result: DecideCaseResult
}): CaseScore {
  const gold = resolveGold({ bookIndex: input.bookIndex, c: input.evalCase })
  const predKeys = new Set(input.result.predictedBookKeys)
  const predPages = new Set<number>()
  for (const k of predKeys) {
    const p = pageOfKey(input.bookIndex, k)
    if (p != null) predPages.add(p)
  }

  const mode = input.evalCase.goldMode ?? 'any'
  let hit = false
  if (gold.pages.size > 0) {
    const inter = [...gold.pages].filter((p) => predPages.has(p))
    hit = mode === 'all' ? inter.length === gold.pages.size : inter.length > 0
  } else if (gold.keys.size > 0) {
    const inter = [...gold.keys].filter((k) => predKeys.has(k))
    hit = mode === 'all' ? inter.length === gold.keys.size : inter.length > 0
  }

  const tp = [...predKeys].filter((k) => gold.keys.has(k)).length
  const precision = predKeys.size === 0 ? 0 : tp / predKeys.size
  const recall = gold.keys.size === 0 ? (hit ? 1 : 0) : tp / gold.keys.size

  return {
    id: input.evalCase.id,
    hit,
    precision,
    recall,
    predictedPages: [...predPages].sort((a, b) => a - b),
    goldPages: [...gold.pages].sort((a, b) => a - b),
    predictedBookKeys: [...predKeys],
    goldBookKeys: [...gold.keys],
  }
}

export function aggregateScores(scores: CaseScore[]): {
  n: number
  hitRate: number
  meanPrecision: number
  meanRecall: number
} {
  const n = scores.length || 1
  return {
    n: scores.length,
    hitRate: scores.filter((s) => s.hit).length / n,
    meanPrecision: scores.reduce((a, s) => a + s.precision, 0) / n,
    meanRecall: scores.reduce((a, s) => a + s.recall, 0) / n,
  }
}

#!/usr/bin/env node
/**
 * Decide material accuracy eval CLI.
 *
 *   npm run eval -- --corpus path/to/x.docuverse.json --eval fixtures/eval.example.json
 *
 * Does not modify the main Docuverse app. Measures CURRENT decide path:
 * qCore prioritize → batched decide → relevance≥3 mintables vs gold keys/pages.
 */

import { writeFileSync, existsSync, readFileSync } from 'node:fs'
import { resolve } from 'node:path'
import { loadCorpusPack, loadEvalFile } from '../src/harness/loadCorpus.ts'
import { loadLlmConfigFromEnv } from '../src/harness/llm.ts'
import { runDecideMaterialSequential } from '../src/harness/runDecideMaterial.ts'
import { aggregateScores, scoreCase } from '../src/harness/score.ts'

function loadDotEnv() {
  const p = resolve(process.cwd(), '.env')
  if (!existsSync(p)) return
  for (const line of readFileSync(p, 'utf8').split(/\r?\n/)) {
    const t = line.trim()
    if (!t || t.startsWith('#')) continue
    const i = t.indexOf('=')
    if (i < 0) continue
    const k = t.slice(0, i).trim()
    let v = t.slice(i + 1).trim()
    if (
      (v.startsWith('"') && v.endsWith('"')) ||
      (v.startsWith("'") && v.endsWith("'"))
    ) {
      v = v.slice(1, -1)
    }
    if (!(k in process.env)) process.env[k] = v
  }
}

function arg(name: string, fallback?: string): string | undefined {
  const i = process.argv.indexOf(name)
  if (i >= 0 && process.argv[i + 1]) return process.argv[i + 1]
  return fallback
}

function hasFlag(name: string): boolean {
  return process.argv.includes(name)
}

async function main() {
  loadDotEnv()
  const corpusPath = arg('--corpus')
  const evalPath = arg('--eval', 'fixtures/eval.example.json')
  const outPath = arg('--out', 'results/decide-eval.json')
  if (!corpusPath) {
    console.error(
      '用法: npm run eval -- --corpus <pack.docuverse.json> --eval <eval.json> [--out results.json] [--toc-union] [--max-keys 400]',
    )
    process.exit(1)
  }

  const pack = loadCorpusPack(resolve(corpusPath))
  const evalFile = loadEvalFile(resolve(evalPath!))
  const llm = loadLlmConfigFromEnv()
  const useTocUnion = hasFlag('--toc-union')
  const maxKeys = Number(arg('--max-keys', '400'))
  const batchSize = Number(arg('--batch', '6'))
  const minProspects = Number(arg('--min-prospects', '10'))

  console.log(
    `corpus=${pack.label} docId=${pack.docId} chunks=${pack.bookIndex.chunks.length}`,
  )
  console.log(`cases=${evalFile.cases.length} model=${llm.model} tocUnion=${useTocUnion}`)

  const caseRows = []
  for (const c of evalFile.cases) {
    console.log(`\n--- ${c.id}: ${c.question}`)
    const result = await runDecideMaterialSequential({
      question: c.question,
      bookIndex: pack.bookIndex,
      semanticIndex: pack.semanticIndex,
      llm,
      options: {
        useTocUnion,
        maxKeys,
        batchSize,
        minProspects,
      },
      onProgress: (m) => console.log('  ', m),
    })
    const scored = scoreCase({
      bookIndex: pack.bookIndex,
      evalCase: c,
      result,
    })
    console.log(
      `  hit=${scored.hit} P=${scored.precision.toFixed(2)} R=${scored.recall.toFixed(2)}` +
        ` predPages=[${scored.predictedPages.join(',')}]` +
        ` tokens≈${result.promptTokens}+${result.completionTokens}` +
        ` · ${result.note}`,
    )
    caseRows.push({ case: c, result, score: scored })
  }

  const agg = aggregateScores(caseRows.map((r) => r.score))
  const payload = {
    at: new Date().toISOString(),
    corpus: { label: pack.label, docId: pack.docId },
    options: { useTocUnion, maxKeys, batchSize, minProspects },
    aggregate: agg,
    cases: caseRows,
  }

  const out = resolve(outPath!)
  writeFileSync(out, JSON.stringify(payload, null, 2), 'utf8')
  console.log('\n=== aggregate ===')
  console.log(
    `n=${agg.n} hitRate=${(agg.hitRate * 100).toFixed(1)}% meanP=${agg.meanPrecision.toFixed(3)} meanR=${agg.meanRecall.toFixed(3)}`,
  )
  console.log(`wrote ${out}`)
}

main().catch((e) => {
  console.error(e)
  process.exit(1)
})

