/**
 * Build ordered noun sequence for a chunk (positions of any S noun),
 * then ±n neighbors that are NOT the hit noun.
 */
export function buildTopoBags(input: {
  bookIndex: BookIndex
  nounById: Map<string, NounEntry>
  hits: ReadonlyArray<NounHit>
  neighborN?: number
  maxBags?: number
}): TopoBag[] {
  const n = input.neighborN ?? 5
  const maxBags = input.maxBags ?? 120

  // Precompute per-chunk noun occurrences: { start, end, id, surface }[]
  const chunkSeq = new Map<
    string,
    Array<{ start: number; end: number; id: string; surface: string }>
  >()
  const allSurfaces = [...input.nounById.values()].sort(
    (a, b) => b.surface.length - a.surface.length,
  )

  function seqFor(chunk: AChunk): Array<{
    start: number
    end: number
    id: string
    surface: string
  }> {
    const cached = chunkSeq.get(chunk.key)
    if (cached) return cached
    const t = atomSearchText(chunk)
    const occ: Array<{ start: number; end: number; id: string; surface: string }> =
      []
    // Greedy left-to-right longest match against S
    let i = 0
    while (i < t.length) {
      let best: { len: number; id: string; surface: string } | null = null
      const slice = t.slice(i)
      for (const e of allSurfaces) {
        if (slice.length < e.surface.length) continue
        if (slice.toLowerCase().startsWith(e.id) || slice.startsWith(e.surface)) {
          const hitLen = slice.toLowerCase().startsWith(e.id)
            ? e.id.length
            : e.surface.length
          // verify case-insensitive match length for surface
          const actual = slice.slice(0, Math.max(hitLen, e.surface.length))
          const matchLen = actual.toLowerCase().startsWith(e.id)
            ? e.id.length
            : e.surface.length
          if (!best || matchLen > best.len) {
            best = { len: matchLen, id: e.id, surface: e.surface }
          }
        }
      }
      if (best && best.len >= 2) {
        occ.push({
          start: i,
          end: i + best.len,
          id: best.id,
          surface: t.slice(i, i + best.len),
        })
        i += best.len
      } else {
        i++
      }
    }
    chunkSeq.set(chunk.key, occ)
    return occ
  }

  const bags: TopoBag[] = []
  for (const hit of input.hits) {
    const chunk = input.bookIndex.chunks.find((c) => c.key === hit.bookKey)
    if (!chunk) continue
    const seq = seqFor(chunk)
    // Find index in seq closest to hit.start
    let idx = seq.findIndex(
      (o) => o.start === hit.start || (o.start <= hit.start && o.end >= hit.end),
    )
    if (idx < 0) {
      idx = seq.findIndex((o) => o.id === hit.nounId)
    }
    if (idx < 0) continue

    const neighborIds: string[] = []
    const seen = new Set<string>()
    // left
    for (let j = idx - 1; j >= 0 && neighborIds.length < n; j--) {
      const id = seq[j]!.id
      if (id === hit.nounId) continue
      if (seen.has(id)) continue
      seen.add(id)
      neighborIds.push(input.nounById.get(id)?.surface ?? seq[j]!.surface)
    }
    neighborIds.reverse()
    const leftCount = neighborIds.length
    // right
    for (let j = idx + 1; j < seq.length && neighborIds.length < leftCount + n; j++) {
      const id = seq[j]!.id
      if (id === hit.nounId) continue
      if (seen.has(id)) continue
      seen.add(id)
      neighborIds.push(input.nounById.get(id)?.surface ?? seq[j]!.surface)
    }

    bags.push({
      bagId: `bag_${bags.length + 1}`,
      hit,
      neighbors: neighborIds,
      bookKey: hit.bookKey,
      page: hit.page,
    })
    if (bags.length >= maxBags) break
  }
  return bags
}

