/**
 * Supervise: does S₀ ∪ S₁ equal / cover 「原来的」O?
 * O = 原文规则抽词去重全量（过滤前）
 */

import {
  buildNounTableLayers,
  maskNounsInText,
  mergeNounEntries,
  normalizeNounSurface,
  type NounEntry,
} from '../core/bookNounIndex.ts'
import { atomSearchText, isRetrievableAtom } from '../core/text.ts'
import type { BookIndex } from '../core/types.ts'
import { chatCompletions, type LlmConfig } from './llm.ts'
import { extractJsonObject } from '../core/parseDecide.ts'

export type SSuperviseReport = {
  kind: 'docuverse-s0-s1-supervise'
  version: 1
  at: string
  corpus: { label: string; docId: string; chunks: number }
  /** 原来的：原文规则抽词去重全量 */
  O: { size: number; sample: string[] }
  S0: { size: number; sample: string[] }
  S1: {
    size: number
    sample: string[]
    residualLlm: boolean
    note: string
    grounded: number
    hallucinated: string[]
  }
  /** U = dedupe(S₀ ∪ S₁) */
  U: { size: number }
  compare: {
    /** |U ∩ O| / |O| */
    coverageOfO: number
    /** |U ∩ O| / |U| */
    precisionVsO: number
    missingFromO: string[]
    extraBeyondO: string[]
    /** missing empty && extra empty */
    equalsO: boolean
    /** S₀ alone vs O */
    s0CoverageOfO: number
    filteredOutByS0: string[]
  }
  verdict: string
  notes: string[]
  promptTokens: number
  completionTokens: number
}

function appearsInBook(bookIndex: BookIndex, id: string): boolean {
  if (id.length < 2) return false
  for (const c of bookIndex.chunks) {
    if (!isRetrievableAtom(c)) continue
    if (atomSearchText(c).toLowerCase().includes(id)) return true
  }
  return false
}

async function runResidualS1(input: {
  bookIndex: BookIndex
  S0: NounEntry[]
  llm: LlmConfig
  maxChars: number
}): Promise<{
  extras: string[]
  note: string
  promptTokens: number
  completionTokens: number
}> {
  const surfaces = input.S0.map((e) => e.surface)
  const parts: string[] = []
  let used = 0
  for (const chunk of input.bookIndex.chunks) {
    if (!isRetrievableAtom(chunk)) continue
    const masked = maskNounsInText(atomSearchText(chunk), surfaces)
    if (!masked.replace(/[_\s]/g, '').length) continue
    const piece = masked.slice(0, 400)
    if (used + piece.length > input.maxChars) break
    parts.push(piece)
    used += piece.length
  }
  if (parts.length === 0) {
    return {
      extras: [],
      note: '残文空 · 跳过 S₁',
      promptTokens: 0,
      completionTokens: 0,
    }
  }
  const chat = await chatCompletions({
    config: input.llm,
    system: '从残文中抽出仍可见的专名/名词。只输出 JSON。不要摘要。不要发明原文没有的词。',
    user:
      '下列文本中已有名词被遮盖为下划线。请列出仍可辨认的专名/名词（必须能在残文中见到）。\n' +
      'JSON: { "nouns": ["…"] }\n\n' +
      parts.join('\n---\n'),
    maxTokens: 2048,
  })
  if (!chat.ok) {
    return {
      extras: [],
      note: `S₁ 失败 · ${chat.note}`,
      promptTokens: 0,
      completionTokens: 0,
    }
  }
  const obj = extractJsonObject(chat.content)
  const nouns = Array.isArray(obj?.nouns)
    ? obj!.nouns.map((x) => String(x).trim()).filter(Boolean)
    : []
  return {
    extras: nouns,
    note: `S₁ 残文补抽 · +${nouns.length}`,
    promptTokens: chat.usage?.prompt_tokens ?? 0,
    completionTokens: chat.usage?.completion_tokens ?? 0,
  }
}

export async function superviseS0S1(input: {
  bookIndex: BookIndex
  corpus: { label: string; docId: string; chunks: number }
  llm: LlmConfig
  residualLlm: boolean
  residualMaxChars?: number
  missingSampleLimit?: number
}): Promise<SSuperviseReport> {
  const limit = input.missingSampleLimit ?? 80
  const layers = buildNounTableLayers(input.bookIndex)
  const O = layers.O
  const S0 = layers.S0
  const Oids = new Set(O.map((e) => e.id))
  const S0ids = new Set(S0.map((e) => e.id))

  let S1surfaces: string[] = []
  let s1Note = '未跑残文 LLM（S₁=∅）'
  let promptTokens = 0
  let completionTokens = 0

  if (input.residualLlm) {
    const fill = await runResidualS1({
      bookIndex: input.bookIndex,
      S0,
      llm: input.llm,
      maxChars: input.residualMaxChars ?? 12000,
    })
    S1surfaces = fill.extras
    s1Note = fill.note
    promptTokens += fill.promptTokens
    completionTokens += fill.completionTokens
  }

  const hallucinated: string[] = []
  const grounded: string[] = []
  for (const s of S1surfaces) {
    const id = normalizeNounSurface(s)
    if (appearsInBook(input.bookIndex, id)) grounded.push(s)
    else hallucinated.push(s)
  }

  const U = mergeNounEntries(S0, grounded, input.bookIndex)
  const Uids = new Set(U.map((e) => e.id))

  const missingFromO = O.filter((e) => !Uids.has(e.id)).map((e) => e.surface)
  const extraBeyondO = U.filter((e) => !Oids.has(e.id)).map((e) => e.surface)
  const filteredOutByS0 = O.filter((e) => !S0ids.has(e.id)).map((e) => e.surface)

  const coverageOfO = O.length === 0 ? 1 : (O.length - missingFromO.length) / O.length
  const precisionVsO = U.length === 0 ? 1 : (U.length - extraBeyondO.length) / U.length
  const s0CoverageOfO =
    O.length === 0 ? 1 : (O.length - filteredOutByS0.length) / O.length
  const equalsO = missingFromO.length === 0 && extraBeyondO.length === 0

  const notes: string[] = [layers.note, s1Note]
  let verdict: string
  if (!input.residualLlm) {
    verdict = equalsO
      ? 'S₀ 已等于 O（无过滤损失）'
      : `未开 S₁：S₀ 覆盖 O 的 ${(s0CoverageOfO * 100).toFixed(1)}%（过滤掉 ${filteredOutByS0.length}）；U=S₀ 不等于 O 属预期，除非关掉过滤`
  } else if (equalsO) {
    verdict = 'S₀∪S₁ 等于 O'
  } else {
    verdict = `S₀∪S₁ 覆盖 O 的 ${(coverageOfO * 100).toFixed(1)}%；缺 ${missingFromO.length} · 多 ${extraBeyondO.length} · 幻觉 ${hallucinated.length}`
  }

  return {
    kind: 'docuverse-s0-s1-supervise',
    version: 1,
    at: new Date().toISOString(),
    corpus: input.corpus,
    O: {
      size: O.length,
      sample: O.slice(0, 40).map((e) => e.surface),
    },
    S0: {
      size: S0.length,
      sample: S0.slice(0, 40).map((e) => e.surface),
    },
    S1: {
      size: grounded.length,
      sample: grounded.slice(0, 40),
      residualLlm: input.residualLlm,
      note: s1Note,
      grounded: grounded.length,
      hallucinated: hallucinated.slice(0, limit),
    },
    U: { size: U.length },
    compare: {
      coverageOfO,
      precisionVsO,
      missingFromO: missingFromO.slice(0, limit),
      extraBeyondO: extraBeyondO.slice(0, limit),
      equalsO,
      s0CoverageOfO,
      filteredOutByS0: filteredOutByS0.slice(0, limit),
    },
    verdict,
    notes,
    promptTokens,
    completionTokens,
  }
}

export function superviseReportToMarkdown(r: SSuperviseReport): string {
  const lines: string[] = []
  lines.push('# S₀+S₁ 监督报告（相对原来的 O）')
  lines.push('')
  lines.push(`- 语料：${r.corpus.label} · chunks=${r.corpus.chunks}`)
  lines.push(`- 时间：${r.at}`)
  lines.push(`- **裁决：${r.verdict}**`)
  lines.push('')
  lines.push('## 定义')
  lines.push('- **O**：原来的 = 原文规则抽词 · 去重全量（不过滤）')
  lines.push('- **S₀**：过滤后的规则表')
  lines.push('- **S₁**：残文 LLM 补抽且能在原文落地的词')
  lines.push('- **U**：去重(S₀∪S₁)')
  lines.push('')
  lines.push('## 规模')
  lines.push(`- |O|=${r.O.size} · |S₀|=${r.S0.size} · |S₁|=${r.S1.size} · |U|=${r.U.size}`)
  lines.push(
    `- 覆盖 O：${(r.compare.coverageOfO * 100).toFixed(2)}% · 相对 O 的精确率：${(r.compare.precisionVsO * 100).toFixed(2)}% · equalsO=${r.compare.equalsO}`,
  )
  lines.push(
    `- 仅 S₀ 覆盖 O：${(r.compare.s0CoverageOfO * 100).toFixed(2)}%（过滤掉 ${r.compare.filteredOutByS0.length}+）`,
  )
  lines.push('')
  lines.push('## O 有而 U 缺（样本）')
  lines.push(r.compare.missingFromO.join(' · ') || '（无）')
  lines.push('')
  lines.push('## U 有而 O 无（样本）')
  lines.push(r.compare.extraBeyondO.join(' · ') || '（无）')
  lines.push('')
  lines.push('## S₁ 幻觉（原文找不到）')
  lines.push(r.S1.hallucinated.join(' · ') || '（无）')
  lines.push('')
  lines.push('## 样本')
  lines.push(`- O：${r.O.sample.join(' · ')}`)
  lines.push(`- S₀：${r.S0.sample.join(' · ')}`)
  lines.push(`- S₁：${r.S1.sample.join(' · ')}`)
  return lines.join('\n')
}

