/**
 * 主验证：mask(U) 后残文分批交给 LLM，问「是否还有名词」。
 * 控窗：每批字符上限，避免注意力被冲垮。
 */
export async function verifyResidualWithLlmBatches(input: {
  bookIndex: BookIndex
  knownSurfaces: ReadonlyArray<string>
  llm: LlmConfig
  charsPerBatch?: number
  maxBatches?: number
  onProgress?: (msg: string) => void
}): Promise<{
  leftover: string[]
  batches: number
  charsPerBatch: number
  promptTokens: number
  completionTokens: number
  notes: string[]
}> {
  const charsPerBatch = input.charsPerBatch ?? 2500
  const maxBatches = input.maxBatches ?? 120
  const batches = residualBatches(
    input.bookIndex,
    input.knownSurfaces,
    charsPerBatch,
  ).slice(0, maxBatches)
  const leftover = new Set<string>()
  const notes: string[] = []
  let promptTokens = 0
  let completionTokens = 0

  notes.push(
    `LLM 验残文 · 批×${batches.length} · 每批≤${charsPerBatch} 字（控注意力）`,
  )

  for (let i = 0; i < batches.length; i++) {
    input.onProgress?.(`LLM 验残文 ${i + 1}/${batches.length}`)
    const chat = await chatCompletions({
      config: input.llm,
      system:
        '你是质检员。文本里已知名词已被去掉（空格替代）。' +
        '判断残文里是否还剩任何名词/专名。只输出 JSON。宁缺毋滥；功能词、冠词、介词不要算名词。',
      user:
        `残文批次 ${i + 1}/${batches.length}：\n\n${batches[i]}\n\n` +
        '若完全没有剩余名词：{ "hasNouns": false, "nouns": [] }\n' +
        '若还有：{ "hasNouns": true, "nouns": ["原文表面形", …] }\n' +
        '禁止发明；禁止把 des/que/les/une/le/la/et/de 等功能词当名词。',
      maxTokens: 1024,
      temperature: 0.1,
    })
    if (!chat.ok) {
      notes.push(`验批${i + 1}失败 · ${chat.note}`)
      continue
    }
    promptTokens += chat.usage?.prompt_tokens ?? 0
    completionTokens += chat.usage?.completion_tokens ?? 0
    const obj = extractJsonObject(chat.content)
    const has = obj?.hasNouns === true
    const nouns = Array.isArray(obj?.nouns)
      ? obj!.nouns.map((x) => String(x).trim()).filter((x) => x.length >= 2 && !/_/.test(x))
      : []
    if (has || nouns.length) {
      for (const n of nouns) leftover.add(n)
    }
  }

  return {
    leftover: [...leftover],
    batches: batches.length,
    charsPerBatch,
    promptTokens,
    completionTokens,
    notes,
  }
}

